/** Trusted React renderer for this Rich Catalog component. */
import React from "react"; import {useRichComponent} from "../../../binding.js"; export function Renderer({surface,component,basePath="/"}){const {properties:p}=useRichComponent(surface,component,basePath);return <section className="anu-rich-table">{p.title&&<h3>{p.title}</h3>}<div className="table-scroll"><table><thead><tr>{p.columns.map(c=><th key={c.key} className={`align-${c.align??"start"}`}>{c.label}</th>)}</tr></thead><tbody>{(p.rows??[]).map((r,i)=><tr key={i}>{p.columns.map(c=><td key={c.key} className={`align-${c.align??"start"}`}>{String(r[c.key]??"")}</td>)}</tr>)}</tbody></table>{!(p.rows??[]).length&&<p>{p.emptyMessage}</p>}</div></section>}
